INSERT INTO `creature_addon` (`guid`, `path_id`, `mount`, `bytes1`, `bytes2`, `emote`, `auras`) SELECT c.`guid`, IF(c.`guid` IN (308544, 308562, 308567), CONCAT('1500', c.`guid`) + 0, 0), IFNULL(t.`mount`, 0), IFNULL(t.`bytes1`, 0), IFNULL(t.`bytes2`, 0), IFNULL(t.`emote`, 0), IFNULL(t.`auras`, '') FROM `creature` c LEFT JOIN `creature_template_addon` t ON t.`entry` = c.`id` WHERE c.`guid` IN (308544, 308549, 309660, 308523, 308514, 308562, 309659, 308547, 308558, 308567, 309565, 309556);
